   136		const prefix = relative(root, fixtureRoot).replaceAll("\\", "/");
   137		const rewrite = (value: unknown): unknown => {
   138			if (typeof value === "string") {
   139				return value.replaceAll("^packages/", `^${prefix}/packages/`);
   140			}
   141			if (Array.isArray(value)) return value.map(rewrite);
   142			if (value && typeof value === "object") {
   143				return Object.fromEntries(
   144					Object.entries(value).map(([key, entry]) => [key, rewrite(entry)]),
   145				);
   146			}
   147			return value;
   148		};
   149		const ruleSet: ControlPlaneRuleSet = structuredClone(dependencyCruiserConfig);
   150		ruleSet.forbidden = ruleSet.forbidden.map(
   151			(rule) => rewrite(rule) as ControlPlaneRuleSet["forbidden"][number],
   152		);
   153	
   154		const result = await cruise([join(fixtureRoot, "packages")], {
   155			baseDir: root,
   156			parser: "swc",
   157			ruleSet,
   158			validate: true,
   159		});
   160		if (typeof result.output === "string") {
